CREATE TABLE IF NOT EXISTS `wallet_transactions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `transactionId` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `type` TEXT NOT NULL, `category` TEXT NOT NULL, `amount` REAL NOT NULL, `balanceAfter` REAL NOT NULL, `gateway` TEXT NOT NULL, `status` TEXT NOT NULL, `hmacSignature` TEXT NOT NULL, `referenceId` TEXT NOT NULL, `description` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `ride_records` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `rideId` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `pickupName` TEXT NOT NULL, `dropName` TEXT NOT NULL, `distanceKm` REAL NOT NULL, `durationMin` INTEGER NOT NULL, `vehicleCategory` TEXT NOT NULL, `vehicleModel` TEXT NOT NULL, `vehiclePlate` TEXT NOT NULL, `pilotName` TEXT NOT NULL, `pilotRating` REAL NOT NULL, `grossFare` REAL NOT NULL, `pilotEarnings` REAL NOT NULL, `platformCut` REAL NOT NULL, `gstTax` REAL NOT NULL, `status` TEXT NOT NULL, `userRating` INTEGER NOT NULL, `feedbackTags` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `user_profile` (`id` INTEGER NOT NULL, `name` TEXT NOT NULL, `email` TEXT NOT NULL, `phone` TEXT NOT NULL, `emergencyContactName` TEXT NOT NULL, `emergencyContactPhone` TEXT NOT NULL, `emergencyRelationship` TEXT NOT NULL, `walletBalance` REAL NOT NULL, `lifetimeSavings` REAL NOT NULL, `autoTopupEnabled` INTEGER NOT NULL, `autoTopupThreshold` REAL NOT NULL, `autoTopupAmount` REAL NOT NULL, `autoDialSos` INTEGER NOT NULL, `defaultPaymentMethod` TEXT NOT NULL, `mapStyle` TEXT NOT NULL, PRIMARY KEY(`id`));
